#!/usr/bin/env python3
"""Reconstruct the exact candidate; validation-only, excluded from product source."""
from pathlib import Path
import base64, hashlib, subprocess, zlib
payload = ""
patch = zlib.decompress(base64.b64decode(payload, validate=True))
assert hashlib.sha256(patch).hexdigest() == "4029181566507eab926f57045c08687ccc0156e4918aba1e6bcd34c209b14133"
subprocess.run(["git", "apply", "--check", "-"], input=patch, check=True)
subprocess.run(["git", "apply", "-"], input=patch, check=True)
proof = Path("/tmp/c5-native-action-proof")
proof.mkdir(parents=True, exist_ok=True)
(proof / "paths.txt").write_text('.github/workflows/native-host-smoke.yml\ncrates/noon-native/src/execution_source.rs\ncrates/noon-native/src/lib.rs\ncrates/noon-native/src/pointer_input.rs\ncrates/noon-native/src/property_animation.rs\ncrates/noon-native/src/property_animation/tests.rs\ncrates/noon/src/live_program/property_animation.rs\ncrates/noon/src/live_program/property_animation/tests.rs\ncrates/noon/src/live_session/pointer_actions.rs\ncrates/noon/src/live_session/pointer_actions/tests.rs\n')
